  "index": 2,
  "title": "הקמת process templates ואוטומציות",
  "titleEn": "Setting Up Process Templates and Automations",
  "level": "מורכב",
  "minutes": 15,
  "trust": "curated",
  "source": "Sales & Operations Planning",
  "prev": "sop-9-1",
