  "title": "ניטור ושיפור מתמיד",
  "titleEn": "Monitoring and Continuous Improvement",
  "level": "מורכב",
  "minutes": 8,
  "trust": "curated",
  "source": "Sales & Operations Planning",
  "prev": "sop-12-2",
